const spell = {
  artifacts: [
    {
      name: 'rain spires', radius: 4, color: '#e8dcc4', lures: ['villager', 'beast'],
      charges: 3, recharge: 90,
      effects: [
        { when: 'dawn', do: 'water', radius: 3, every: 240 },
        { when: 'drought', do: 'rain', radius: 4, every: 60, cost: 1 },
      ],
      grants: [{ what: 'water', cost: 1 }],
    },
  ],
  *cast(w) {
    const d = w.r * 0.6;
    for (let k = 0; k < 3; k++) {
      const a = k * 2.094 + 0.5;
      const x = w.x + Math.cos(a) * d, y = w.y + Math.sin(a) * d;
      const h = 14 + k * 2;
      w.spire(x, y, { height: h, radius: 2, colors: ['#e8dcc4', '#d9c9a6'], kind: 'stone' });
      w.sphere(x, y, h - 1, 1.4, ['#9fe3ff', '#d8f6ff'], 0.9, 'glow');
    }
  },
};
